files.content:
.benos-select {
  color: var(--benos-color-text);
  display: grid;
  font-size: var(--benos-text-xs, 0.75rem);
  gap: var(--benos-space-2);
  position: relative;
}

.benos-select__label {
  font-size: var(--benos-text-xs, 0.75rem);
  font-weight: 600;
}

.benos-select__control {
  align-items: center;
  background: var(--benos-color-surface);
  border: 1px solid var(--benos-color-border);
  border-radius: var(--benos-radius-md);
  display: flex;
  min-block-size: 2.5rem;
}

.benos-select__trigger,
.benos-select__clear {
  align-items: center;
  background: transparent;
  border: 0;
  color: var(--benos-color-text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  gap: var(--benos-space-2);
  min-block-size: 2.5rem;
  padding-block: var(--benos-space-2);
}

.benos-select__trigger {
  flex: 1;
  justify-content: space-between;
  min-inline-size: 0;
  padding-inline: var(--benos-space-3);
  text-align: start;
}

.benos-select__clear {
  justify-content: center;
  min-inline-size: 2.5rem;
  padding-inline: var(--benos-space-2);
  border-inline-start: 1px solid var(--benos-color-border);
}

.benos-select__control:focus-within {
  outline: 3px solid var(--benos-color-focus);
  outline-offset: 2px;
}

.benos-select__trigger:focus-visible,
.benos-select__clear:focus-visible {
  outline: none;
}

.benos-select[data-invalid='true'] .benos-select__trigger {
  border-color: var(--benos-color-danger);
}

.benos-select[data-disabled] .benos-select__trigger,
.benos-select[data-disabled] .benos-select__clear {
  cursor: not-allowed;
  opacity: 0.58;
}

.benos-select__chevron {
  background: currentColor;
  block-size: 0.5rem;
  clip-path: polygon(0 0, 50% 62%, 100% 0, 100% 34%, 50% 100%, 0 34%);
  flex: none;
  inline-size: 0.75rem;
}

.benos-select__positioner {
  z-index: var(--benos-z-dropdown, 10);
}

.benos-select__content {
  background: var(--benos-color-surface-raised);
  border: 1px solid var(--benos-color-border);
  border-radius: var(--benos-radius-md);
  box-shadow: var(--benos-shadow-md);
  color: var(--benos-color-text);
  inline-size: max(12rem, var(--reference-width, 100%));
  max-block-size: 16rem;
  overflow-y: auto;
  padding: var(--benos-space-1);
}

.benos-select__content[hidden],
.benos-select__content[data-state='closed'] {
  display: none;
}

.benos-select__item {
  align-items: center;
  border-radius: var(--benos-radius-sm);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  min-block-size: 2.25rem;
  padding-block: var(--benos-space-2);
  padding-inline: var(--benos-space-2);
}

.benos-select__item[data-highlighted] {
  background: var(--benos-color-brand-soft);
  outline: none;
}

.benos-select__item[data-disabled] {
  cursor: not-allowed;
  opacity: 0.58;
}

.benos-select__check {
  color: var(--benos-color-brand);
  opacity: 0;
}

.benos-select__check[data-selected] {
  opacity: 1;
}
